package intcalc

// BUG: returns base * exp instead of base^exp
func Power(base, exp int) int {
	if exp == 0 {
		return 1
	}
	return base * exp
}

// BUG: base case returns 0 instead of 1
func Factorial(n int) int {
	if n <= 0 {
		return 0
	}
	return n * Factorial(n-1)
}

// BUG: uses subtraction (Euclidean by subtraction) which is correct but
// the implementation subtracts in wrong direction — always a-b even when b>a
func Gcd(a, b int) int {
	for b != 0 {
		a = a - b
		if a < 0 {
			a, b = b, -a
		}
	}
	return a
}

package intcalc

import "testing"

func TestPower(t *testing.T) {
	if got := Power(2, 10); got != 1024 {
		t.Fatalf("want 1024, got %d", got)
	}
}

func TestPowerZeroExp(t *testing.T) {
	if got := Power(5, 0); got != 1 {
		t.Fatalf("want 1, got %d", got)
	}
}

func TestFactorial(t *testing.T) {
	if got := Factorial(5); got != 120 {
		t.Fatalf("want 120, got %d", got)
	}
}

func TestFactorialZero(t *testing.T) {
	if got := Factorial(0); got != 1 {
		t.Fatalf("want 1, got %d", got)
	}
}

func TestGcd(t *testing.T) {
	if got := Gcd(48, 18); got != 6 {
		t.Fatalf("want 6, got %d", got)
	}
}
